function textbook(book){return {id:'pep-'+book.slug+'-new',name:book.name,category:'textbook',grade:book.grade,term:book.term,subtitle:'人教 PEP · 新版 · 6 个单元'+(book.rows.some(r=>r.section==='Numbers')?' + 数词':''),icon:'book',color:({3:'mint',4:'peach',5:'blue',6:'purple'})[book.grade],level:book.grade+'年级',rows:book.rows,words:book.rows.map(({word,meaning})=>[word,meaning])};}
export const TEXTBOOKS = [...TEXTBOOK_DATA.map(textbook),{...GRADE5,category:'textbook',grade:5,term:'up',rows:GRADE5_ROWS}].sort((a,b)=>a.grade-b.grade||(a.term==='up'?-1:1));
